# Fix the function order and calculate total files
def get_all_files(structure, path=""):
    """Get all file paths from structure"""
    for key, value in structure.items():
        current_path = f"{path}/{key}" if path else key
        if isinstance(value, dict):
            yield from get_all_files(value, current_path)
        else:
            yield current_path

# Calculate total files
all_files = list(get_all_files(structure))
print(f"🎯 Total files to be created: {len(all_files)}")
print("\n📋 Complete file list (first 15):")
for i, file_path in enumerate(all_files[:15], 1):
    print(f"{i:2d}. {file_path}")
if len(all_files) > 15:
    print(f"    ... and {len(all_files) - 15} more files")

print("\n🚀 Ready to generate all files!")
